'use strict';
(()=>{const make=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
const textLabel=value=>{const text=String(value||'').trim().normalize('NFKC'),char=[...text.toLocaleUpperCase()][0];return !char?'#':/\d/.test(char)?'0–9':/\p{L}/u.test(char)?char:'#';};
function sizeLabel(bytes){const mb=Math.max(0,Number(bytes)||0)/1048576,bounds=[0,1,5,10,25,50,100,250,500,1024,2048,5120,10240,51200,102400];let i=0;while(i<bounds.length-1&&mb>=bounds[i+1])i++;const value=n=>n>=1024?(n/1024)+' GB':n+' MB';return i===bounds.length-1?value(bounds[i])+'+':value(bounds[i])+'–'+value(bounds[i+1]);}
function dateLabel(value){const d=new Date(value);if(!value||!Number.isFinite(d.getTime()))return 'Date unknown';return d.toLocaleDateString(undefined,{month:'short',year:'numeric',timeZone:'UTC'});}
function durationLabel(seconds){const minutes=Math.max(0,Number(seconds)||0)/60,step=minutes>=60?30:minutes>=10?5:1,start=Math.floor(minutes/step)*step;return start>=60?(start/60).toLocaleString(undefined,{maximumFractionDigits:1})+' h+':start+'–'+(start+step)+' min';}
function create(shelf,{selector,onJump,description='Jump through this collection'}){const wrapper=make('div',undefined,'catalog-jump-layout');shelf.before(wrapper);wrapper.append(shelf);const rail=make('aside',undefined,'catalog-jump-rail'),range=make('input'),bubble=make('output',undefined,'catalog-jump-bubble'),ticks=make('div',undefined,'catalog-jump-ticks');range.type='range';range.min='0';range.max='0';range.step='1';range.value='0';range.setAttribute('aria-label',description);range.setAttribute('orient','vertical');rail.append(ticks,range,bubble);wrapper.append(rail);let entries=[],labels=[],dragging=false,timer=null,lastIndex=-1;function show(index){index=Math.max(0,Math.min(entries.length-1,Number(index)||0));range.value=String(index);const label=labels[index]||'';range.setAttribute('aria-valuetext',label+' · '+(index+1)+' of '+entries.length);bubble.textContent=label;bubble.style.top=(entries.length<2?0:index/(entries.length-1)*100)+'%';rail.dataset.activeLabel=label;}
function jump(index){if(!entries.length)return;index=Math.max(0,Math.min(entries.length-1,Number(index)||0));show(index);onJump(index);const target=shelf.querySelector('[data-jump-index="'+index+'"]');if(target)shelf.scrollTop+=target.getBoundingClientRect().top-shelf.getBoundingClientRect().top-8;lastIndex=index;}
range.oninput=()=>{show(range.value);rail.classList.add('scrubbing');clearTimeout(timer);timer=setTimeout(()=>jump(Number(range.value)),90);};range.onchange=()=>{clearTimeout(timer);jump(Number(range.value));if(!dragging)rail.classList.remove('scrubbing');};range.onpointerdown=()=>{dragging=true;rail.classList.add('scrubbing');};for(const name of ['pointerup','pointercancel'])range.addEventListener(name,()=>{dragging=false;clearTimeout(timer);jump(Number(range.value));rail.classList.remove('scrubbing');});
let scheduled=false;function sync(){scheduled=false;if(dragging||!entries.length)return;const top=shelf.getBoundingClientRect().top+8,nodes=[...shelf.querySelectorAll(selector)];if(nodes.length&&shelf.scrollTop+shelf.clientHeight>=shelf.scrollHeight-2&&Number(nodes.at(-1).dataset.jumpIndex)===entries.length-1){show(entries.length-1);return;}let item=nodes.find(n=>n.getBoundingClientRect().bottom>top);if(item)show(item.dataset.jumpIndex);}
shelf.addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(sync);}},{passive:true});const observer=new MutationObserver(()=>{if(!dragging)requestAnimationFrame(sync);});observer.observe(shelf,{childList:true,subtree:true});
return {update(items,label,mode='Title'){entries=items;labels=items.map(label);range.max=String(Math.max(0,items.length-1));range.setAttribute('aria-label','Jump by '+mode);rail.hidden=items.length<40;wrapper.classList.toggle('has-jump-rail',!rail.hidden);ticks.replaceChildren();const anchors=[];let previous=null;for(let i=0;i<labels.length;i++)if(labels[i]!==previous){anchors.push({index:i,label:labels[i]});previous=labels[i];}let chosen=anchors.length<=8?anchors:Array.from({length:8},(_,i)=>anchors.reduce((best,a)=>Math.abs(a.index-i*(items.length-1)/7)<Math.abs(best.index-i*(items.length-1)/7)?a:best,anchors[0]));chosen=[...new Map(chosen.map(a=>[a.index,a])).values()];const height=rail.clientHeight||400;chosen=chosen.filter((a,i,all)=>i===0||(a.index-all[i-1].index)/Math.max(1,items.length-1)*height>=34);for(const anchor of chosen){const button=make('button',anchor.label);button.type='button';button.style.top=(items.length<2?0:anchor.index/(items.length-1)*100)+'%';button.setAttribute('aria-label','Jump to '+anchor.label);button.title=anchor.label;button.onclick=()=>jump(anchor.index);ticks.append(button);}if(!dragging)sync();},jump};}
window.MAHA_JUMP_RAIL={create,textLabel,sizeLabel,dateLabel,durationLabel};
// Books retain their existing render wrappers and catalog-state behavior.
document.addEventListener('DOMContentLoaded',()=>{const shelf=document.getElementById('books');if(!shelf)return;const rail=create(shelf,{selector:'.book[data-jump-index]',onJump:index=>{window.MAHA_BOOK_JUMP_START=Math.max(0,index-24);limit=index+72;shelf.scrollTop=0;render();}});function update(){const items=window.MAHA_BOOK_JUMP_ITEMS||[],sort=document.getElementById('book-sort')?.value;rail.update(items,sort==='newest'||sort==='oldest'?b=>dateLabel(b.importedAt||b.addedAt):b=>textLabel(b.title),sort==='newest'||sort==='oldest'?'date added':'title');}new MutationObserver(update).observe(shelf,{childList:true});shelf.addEventListener('scroll',()=>{const start=window.MAHA_BOOK_JUMP_START||0;if(shelf.scrollTop<70&&start>0){const oldHeight=shelf.scrollHeight,oldTop=shelf.scrollTop;window.MAHA_BOOK_JUMP_START=Math.max(0,start-24);render();shelf.scrollTop=oldTop+shelf.scrollHeight-oldHeight;}},{passive:true});update();});
})();
